<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response};use App\Repositories\{PakistanErpRepository,SettingsRepository};use App\Support\Flash;
final class AcademicProfilesController extends AdminPageController{private function i():int{return(int)(new SettingsRepository($this->app->database()))->institute()['id'];}private function r():PakistanErpRepository{return new PakistanErpRepository($this->app->database());}public function index(Request$q):Response{return$this->view('settings/academic-profiles',['pageTitle'=>'Academic Configuration','activeMenu'=>'general-settings','activeSubmenu'=>'academic-profiles','institute'=>(new SettingsRepository($this->app->database()))->institute(),'sessions'=>$this->r()->sessions($this->i()),'profiles'=>$this->r()->profiles($this->i())]);}public function session(Request$q):Response{try{$this->r()->saveSession($this->i(),trim((string)$q->input('name')),(string)$q->input('start_date'),(string)$q->input('end_date'));Flash::add('success','Academic session saved.');}catch(\Throwable$e){Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/settings/academic-profiles'));}public function profile(Request$q):Response{$type=(string)$q->input('institute_type');$attendance=(float)$q->input('min_attendance');$pass=(float)$q->input('pass_threshold');if(!in_array($type,['internal','coaching','fbise','provincial_bise','custom'],true)||$attendance<0||$attendance>100||$pass<0||$pass>100)return Response::html('Invalid academic profile',422);$grades=[];if($type==='fbise')$grades=[['A++',96,100,'pass'],['A+',91,95.99,'pass'],['A',86,90.99,'pass'],['B++',81,85.99,'pass'],['B+',76,80.99,'pass'],['B',71,75.99,'pass'],['C+',61,70.99,'pass'],['C',51,60.99,'pass'],['D',40,50.99,'pass'],['U',0,39.99,'fail']];$id=$this->r()->saveProfile($this->i(),['session_id'=>(int)$q->input('session_id')?:null,'name'=>trim((string)$q->input('name')),'institute_type'=>$type,'board_name'=>trim((string)$q->input('board_name'))?:null,'min_attendance'=>$attendance,'pass_threshold'=>$pass,'absent_counts_as_zero'=>$q->input('absent_counts_as_zero')?1:0,'is_default'=>$q->input('is_default')?1:0,'effective_from'=>(string)$q->input('effective_from')?:null,'effective_to'=>(string)$q->input('effective_to')?:null,'applicable_levels'=>trim((string)$q->input('applicable_levels'))?:null],$grades);$this->r()->audit($this->i(),(int)user()['id'],'academic_profile.created','academic_rule_profile',$id);Flash::add('success','Academic rule profile saved.');return Response::redirect(url('/admin/settings/academic-profiles'));}}
